function validate([numberOfUsers, events]) {
  if (numberOfUsers < 1 || numberOfUsers > 100) return 'numberOfUsers is between 1 and 100.';
  if (events.length < 1 || events.length > 100) return 'events needs 1 to 100 events.';
  const isUser = text => /^(0|[1-9]\d*)$/.test(text) && Number(text) < numberOfUsers;
  for (const event of events) {
    if (event.length !== 3) return 'Each event is three strings: [type, timestamp, data].';
    const [type, time, data] = event;
    if (!/^[1-9]\d*$/.test(time) || Number(time) > 100000) return 'Each timestamp is a whole number from 1 to 10^5.';
    if (type === 'OFFLINE') {
      if (!isUser(data)) return 'An OFFLINE event names a user id from 0 to numberOfUsers - 1.';
    } else if (type === 'MESSAGE') {
      const tokens = data.split(' ');
      if (data !== 'ALL' && data !== 'HERE' && (tokens.length > 100 || tokens.some(token => !token.startsWith('id') || !isUser(token.slice(2))))) return 'A message is ALL, HERE, or 1 to 100 ids such as "id0 id2", separated by single spaces.';
    } else return 'Each event type is MESSAGE or OFFLINE.';
  }
  // A user can only go offline while online.
  const offline = events.filter(event => event[0] === 'OFFLINE').map(event => [Number(event[1]), Number(event[2])]).sort((a, b) => a[0] - b[0]);
  const onlineAt = new Array(numberOfUsers).fill(0);
  for (const [time, user] of offline) {
    if (onlineAt[user] > time) return `User ${user} goes offline at ${time} while already offline.`;
    onlineAt[user] = time + 60;
  }
  return null;
}

