function countMentions(numberOfUsers, events) {
  const rank = event => (event[0] === 'OFFLINE' ? 0 : 1);
  const sorted = [...events].sort((a, b) => Number(a[1]) - Number(b[1]) || rank(a) - rank(b));
  const mentions = new Array(numberOfUsers).fill(0);
  const onlineAt = new Array(numberOfUsers).fill(0);

  for (const [type, time, data] of sorted) {
    const now = Number(time);
    if (type === 'OFFLINE') {
      onlineAt[Number(data)] = now + 60;
    } else if (data === 'ALL') {
      for (let user = 0; user < numberOfUsers; user++) {
        mentions[user]++;
      }
    } else if (data === 'HERE') {
      for (let user = 0; user < numberOfUsers; user++) {
        if (onlineAt[user] <= now) {
          mentions[user]++;
        }
      }
    } else {
      for (const token of data.split(' ')) {
        mentions[Number(token.slice(2))]++;
      }
    }
  }
  return mentions;
}

