function countMentions(numberOfUsers, events) {
  // No sorting: a user is offline at time t when some OFFLINE event for them started at s with s <= t < s + 60.
  const offline = (user, t) => events.some(([type, at, id]) => type === 'OFFLINE' && Number(id) === user && Number(at) <= t && t < Number(at) + 60);
  const counts = Array(numberOfUsers).fill(0);
  for (const [type, at, data] of events) {
    if (type !== 'MESSAGE') continue;
    if (data === 'ALL' || data === 'HERE') {
      for (let user = 0; user < numberOfUsers; user++) if (data === 'ALL' || !offline(user, Number(at))) counts[user] += 1;
    } else {
      for (const word of data.split(' ')) counts[parseInt(word.replace('id', ''), 10)] += 1;
    }
  }
  return counts;
}

