function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const numberOfUsers = large ? 50 + pick(51) : 1 + pick(4);
  const count = large ? 100 : 1 + pick(8);
  const onlineAt = new Array(numberOfUsers).fill(0);
  const events = [];
  let time = 1 + pick(60);
  for (let i = 0; i < count; i++) {
    // Steps of 0, 59, 60 or 61 make shared timestamps and returns at exactly timestamp + 60 common.
    if (i > 0) time = Math.min(100000, time + (pick(2) ? [0, 1, 30, 59, 60, 61][pick(6)] : pick(large ? 2000 : 120)));
    const ready = [];
    for (let user = 0; user < numberOfUsers; user++) if (onlineAt[user] <= time) ready.push(user);
    if (ready.length > 0 && pick(3) === 0) {
      const user = ready[pick(ready.length)];
      onlineAt[user] = time + 60;
      events.push(['OFFLINE', String(time), String(user)]);
      continue;
    }
    const kind = pick(5);
    const ids = Array.from({ length: 1 + pick(large ? 100 : 4) }, () => 'id' + pick(numberOfUsers));
    events.push(['MESSAGE', String(time), kind === 0 ? 'ALL' : kind <= 2 ? 'HERE' : ids.join(' ')]);
  }
  // The input does not have to be in time order.
  for (let i = events.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [events[i], events[j]] = [events[j], events[i]];
  }
  return [numberOfUsers, events];
}
